"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4618],{1463(e){e.exports=JSON.parse('{"title":"LLM\uc758 \ubd88\ud655\uc2e4\uc131\uc744 \ub514\uc790\uc778\ud558\uae30","date":"2026-07-14","coverUrl":"/kudzu-based-bench/assets/notion/18381c2626575906.png","html":"<h1 data-notion-block-id=\\"387e548d-8a8e-80f4-b7f8-cdaf8fffcb4b\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"38ae548d-8a8e-8055-b05c-f6c9732d14df\\" id=\\"38ae548d-8a8e-8055-b05c-f6c9732d14df\\">LLM\uc758 \ubd88\ud655\uc2e4\uc131\uc744 \ub514\uc790\uc778\ud558\uae30</h2><a href=\\"https://www.smashingmagazine.com/2026/06/designing-uncertainty-how-ai-supercharges-probabilistic-thinking/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2026/06/designing-uncertainty-how-ai-supercharges-probabilistic-thinking/</a><p data-notion-block-id=\\"689d9e59-a2d9-4240-a89a-f9b3c9848326\\">AI\ub97c \uc4f4 UI/UX\ub97c \ub9cc\ub4e4 \ub54c\uc758 \uc5ec\uc12f \uc6d0\uce59\uc740 \uadf8 \uc790\ub9ac\uc5d0\uc120 \ub9de\ub294 \ub9d0\uc778\ub370 \ub2e4\uc74c \uc2a4\ud504\ub9b0\ud2b8\uba74 \uc78a\ud788\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc774 \ub2e4\ub978 \uac74 \uc6d0\uce59\ub9cc \uc8fc\ub294 \uac8c \uc544\ub2c8\ub77c \uadf8 \uc6d0\uce59\uc774 \uc65c \uc78a\ud788\uace0 \ubb34\ub108\uc9c0\ub294\uc9c0\ub97c \uac19\uc774 \uc9da\ub294\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \uae00\uc774 \uc790\uae30 \ucc98\ubc29\uc5d0 \uc2a4\uc2a4\ub85c \ub2e8\uc11c\ub97c \ub2e4\ub294 \ub300\ubaa9\uc774\uc694. \ud734\uba3c\uc778\ub354\ub8e8\ud504\ub294 \ud615\uc2dd\uc801 \uace0\ubb34\ub3c4\uc7a5\uc774 \ub418\uae30 \uc27d\uace0, \uc2dc\ubbac\ub808\uc774\uc158\uc740 \uacfc\uac70\ub9cc \ube44\ucd9c \ubfd0 \ubbf8\ub798\ub294 \ubabb \ub9de\ud799\ub2c8\ub2e4. \uc88b\uc740 \ucc98\ubc29\ub3c4 \uc2e4\uc804\uc5d0\uc11c \uc870\uc6a9\ud788 \uc5b4\uae0b\ub0a0 \uc218 \uc788\ub2e4\ub294 \uacb0\uc5d0\uc11c\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/379e548d-8a8e-801f-81b6-cd51ddeef0a7#381e548d-8a8e-807d-996a-dc8e61f05c23\\">\uc5d0\uc774\uc804\ud2b8 \ud14c\uc2a4\ud2b8\ub294 \uc5b4\ub514\uc5d0 \uc5b9\ud788\ub294\uac00</a>\uc640 \ud568\uaed8 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"39de548d-8a8e-8178-8784-fd777102fca7\\" id=\\"39de548d-8a8e-8178-8784-fd777102fca7\\">Linear, styled-components\uc5d0\uc11c StyleX\ub85c</h2><a href=\\"https://www.skovhus.dev/blog/moving-linear-from-styled-components-to-stylex\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.skovhus.dev/blog/moving-linear-from-styled-components-to-stylex</a><p data-notion-block-id=\\"09868681-7bdc-46a9-ab38-9b8d5406437a\\">styled-components\ub97c \ub5a0\ub098 \ube4c\ub4dc \ud0c0\uc784\uc5d0 \uc6d0\uc790\uc801 CSS\ub97c \ubf51\ub294 \ubc29\ud5a5 \uc790\uccb4\ub294 \uc0c8\ub86d\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uad00\ub9ac \ubaa8\ub4dc\uc5d0 \ub4e4\uc5b4\uac04 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc5b4\ub5bb\uac8c \uac77\uc5b4\ub0b4\ub290\ub0d0\ub294 \ubb3c\uc74c\uc740 \uc5c5\uacc4\uac00 \ud55c\ub3d9\uc548 \ubd99\ub4e4\ub358 \uac83\uc774\uace0, \uac19\uc740 \uc774\uc720\ub85c styled-components\ub97c \ube60\uc838\ub098\uac04 <a href=\\"https://ones-to-watch.ethansup.net/news/post/262e548d-8a8e-80eb-9e8b-cd0868f2c950#27be548d-8a8e-800d-b363-ceed9a4d4fb9\\">Sanity\uc758 \uc0ac\ub840</a>\ub3c4 \uc774\ubbf8 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \ub5a0\ub09c \uba85\ubd84\uc740 \ud55c \ubc88 \ub354 \ubcfc \ub9cc\ud569\ub2c8\ub2e4. styled-components\uac00 \uad00\ub9ac \ubaa8\ub4dc\ub77c React 18\uc758 useInsertionEffect\ub97c \uc548 \ubc1b\uc558\ub2e4\ub294 \uac8c \ucd9c\ubc1c\uc810\uc778\ub370, <a href=\\"https://styled-components.com/releases#styled-components@6.3.7\\">\ub9b4\ub9ac\uc2a4 \uae30\ub85d</a>\uc744 \ubcf4\uba74 \uadf8 \ub4a4\ub85c\ub3c4 \ud328\uce58\uac00 \uc774\uc5b4\uc84c\uace0 v7 \ub77c\uc778\uc740 React 19\ub97c \uaca8\ub0e5\ud569\ub2c8\ub2e4. \uc8fd\uc5b4\uc11c \ub5a0\ub0ac\ub2e4\uae30\ubcf4\ub2e4 \uadf8 \uc2dc\uc810\uc758 \ud310\ub2e8\uc774\uc5c8\ub2e4\uace0 \uc77d\ub294 \ud3b8\uc774 \uc815\ud655\ud569\ub2c8\ub2e4. \uc815\uc791 \ub208\uc5ec\uaca8\ubcfc \uac74 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \uc5d0\uc774\uc804\ud2b8\uc5d0 \uc881\uc740 \uc791\uc5c5\uacfc \uac80\uc99d \uc2a4\ud06c\ub9bd\ud2b8\ub85c \ucabc\uac1c \uad74\ub9b0 \ubc29\ubc95\uc774\uace0, \uae30\uc874 \ud14c\uc2a4\ud2b8\ub97c \uc7ac\uc0ac\uc6a9\ud574 \uac80\uc99d\ud55c <a href=\\"https://ones-to-watch.ethansup.net/news/post/34ae548d-8a8e-8089-b1db-c322e570f0aa#34ae548d-8a8e-8053-8d15-c8afffac1c8b\\">Oxc\ud300\uc758 Claude Code\xb7Codex \ud65c\uc6a9\uae30</a>\uc640 \uac19\uc740 \uacb0\uc785\ub2c8\ub2e4. \uc7a5\uc810\uacfc \ub2e8\uc810\uc744 \ubaa8\ub450 \ub2e4\ub8e8\uace0 \uc788\uc73c\ub2c8 \ud55c \ubc88 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5b5ce584-abb4-49c5-8c6b-9ce593130354\\" id=\\"5b5ce584-abb4-49c5-8c6b-9ce593130354\\">\uacb0\uad6d, \uc870\uc9c1\uc774 \ubc14\ub00c\uc5b4\uc57c \ud55c\ub2e4.</h2><a href=\\"https://zeroheight.com/blog/design-system-documentation-is-everywhere-but-belongs-to-no-one/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://zeroheight.com/blog/design-system-documentation-is-everywhere-but-belongs-to-no-one/</a><a href=\\"https://zeroheight.com/blog/eliminate-the-back-and-forth-in-developer-handovers-with-ai-agents/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://zeroheight.com/blog/eliminate-the-back-and-forth-in-developer-handovers-with-ai-agents/</a><p data-notion-block-id=\\"da6d6a0c-c654-4684-afff-568266615a69\\">\uc870\uc9c1\uc5d0 \ubb38\uc11c\ub294 \ub9ce\uc9c0\ub9cc \uc11c\ub85c \ub530\ub85c \ub180\uace0, \uc65c \uc774\ub807\uac8c \ud588\ub294\uc9c0 \ud788\uc2a4\ud1a0\ub9ac \ucd94\uc801\uc774 \uc548 \ub41c\ub2e4\ub294 \ubb38\uc81c\ub97c \uc81c\uc2dc\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc608\uc804\uc5d0\ub294 \uc0ac\ub78c\uc774 \ub208\uce58\uc640 \ub9e5\ub77d\uc73c\ub85c \uadf8 \ube48\uce78\uc744 \uba54\uc6e0\uc9c0\ub9cc, AI\ub294 \uadf8\ub7ec\uc9c0 \ubabb\ud558\uace0 \ube48 \uacf3\uc744 \uadf8\ub0e5 \uadf8\ub7f4\ub4ef\ud558\uac8c \ucc44\uc6c1\ub2c8\ub2e4. \uadf8\ub798\uc11c \uae00\uc740 \ubb38\uc11c\uc758 \uae30\uc900\uc744 \ub204\uac00 \uc138\uc6b0\uace0 \ub204\uac00 \ucc45\uc784\uc9c8\uc9c0\ubd80\ud130 \uc815\ud558\uc790\uace0 \ud569\ub2c8\ub2e4. \ub2e4\ub9cc \uadf8\uac8c \uc870\uc9c1\ub3c4\ub9cc \ub2e4\uc2dc \uadf8\ub9ac\ub294 \uac78\ub85c \ub05d\ub098\uba74 \uc2e4\uc81c\ub85c \ub2ec\ub77c\uc9c0\ub294 \uac74 \uc5c6\uc2b5\ub2c8\ub2e4. \uc774 \uc5ed\ud560\uc744 \ub9e1\uc744 \uacf3\uc73c\ub85c \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc774 \uaf3d\ud788\ub294\ub370, \ubb38\uc11c\ub97c \uc804\ubd80 \ub5a0\ub9e1\uae30\uba74 \uc624\ud788\ub824 \uc77c\uc774 \uadf8\ucabd\uc73c\ub85c \ubab0\ub824 \ubcd1\ubaa9\uc774 \ub429\ub2c8\ub2e4. \uadf8\ub798\uc11c <a href=\\"https://ones-to-watch.ethansup.net/news/post/d4f23197-313d-4572-8daa-b392343947bb#125e548d-8a8e-80d6-8279-d170303bb1e8\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc774 \uc815\ub9d0 \ud544\uc694\ud55c\uac00\uc694?</a>\uc758 \uacbd\uace0\uac00 \uc5ec\uae30\uc11c\ub3c4 \ud1b5\ud569\ub2c8\ub2e4. \uacb0\uad6d \uc18c\uc720\ub294 \ub9d0\ub85c \uc815\ud558\ub294 \uac8c \uc544\ub2c8\ub77c \uc77c\ud558\ub294 \uacfc\uc815\uc5d0 \ub07c\uc6cc \ub123\uc5b4\uc57c \uad74\ub7ec\uac11\ub2c8\ub2e4. \ucf54\ub4dc\uc5d0\uc120 \uc774\ubbf8 \uadf8\ub807\uac8c \ud558\uc8e0. <a href=\\"https://ones-to-watch.ethansup.net/news/post/2dbe548d-8a8e-8032-b1c2-ec78ab7314d0#2e6e548d-8a8e-8093-9a60-d7c1e2fc0007\\">TypeScript \ucf54\ub4dc\ubca0\uc774\uc2a4\uac00 \ucee4\uc84c\uc744 \ub54c</a>\ub97c \ubcf4\uba74 \uc0c8 \ud30c\uc77c\uc774 \ud558\ub098 \uc0dd\uae30\ub294 \uc21c\uac04 CODEOWNERS\uac00 \uc774\uac74 \ub124 \ub2f4\ub2f9\uc774\ub77c\uace0 \uc790\ub3d9\uc73c\ub85c \ubd99\uc5ec\uc90d\ub2c8\ub2e4. \ubb38\uc11c\ub3c4 \uc774\ub807\uac8c, \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uadf8 \uc21c\uac04\uc5d0 \ub2f4\ub2f9\uacfc \uaddc\uce59\uc774 \uac19\uc774 \ub538\ub824\uc624\uac8c \ud574\uc57c \uae00\uc774 \uac15\uc870\ud55c \uc65c \uc801\uae30\ub3c4 \ud750\uc9c0\ubd80\uc9c0\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"38be548d-8a8e-81ab-aeff-cddd06f331d0\\" id=\\"38be548d-8a8e-81ab-aeff-cddd06f331d0\\">postinstall scripts\ub97c \ub9c9\ub294\ub2e4\uace0 \ubcf4\uc548\uc774 \ub05d\ub098\ub0d0?</h2><a href=\\"https://nodesource.com/blog/npm-v12-install-scripts-not-a-silver-bullet\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodesource.com/blog/npm-v12-install-scripts-not-a-silver-bullet</a><p data-notion-block-id=\\"38be548d-8a8e-81d0-9d1e-feb4670a4165\\">npm v12\uac00 <a href=\\"https://github.blog/changelog/2026-06-09-upcoming-breaking-changes-for-npm-v12/\\">install \uc2a4\ud06c\ub9bd\ud2b8\ub97c \uae30\ubcf8 \ucc28\ub2e8\uc73c\ub85c \ubc14\uafbc \uac83</a>\uc744 \ub450\uace0 \uadf8\uac83\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0, \ub2e4\uc911 \ubc29\uc5b4\uccb4\uacc4\ub97c \uad6c\ucd95\ud574\uc57c \ud55c\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://ones-to-watch.ethansup.net/news/post/2c6e548d-8a8e-80b8-b96f-c0656a397504#2cae548d-8a8e-8034-a280-c0782647987d\\">pnpm\uc758 \ub2e4\uc911\ubc29\uc5b4\uccb4\uacc4\ub97c \ubcf4\ub294 \uac83</a>\ub3c4 \uc758\ubbf8\uac00 \uc788\uaca0\ub124\uc694.</p><h1 data-notion-block-id=\\"4a044e55-bbf5-4946-8295-39aa1c91cfe9\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"9d3d4ee7-9308-4354-84d0-b705c19ea1f1\\" id=\\"9d3d4ee7-9308-4354-84d0-b705c19ea1f1\\">\ub4dc\ub86d\ub2e4\uc6b4 \ub300\uc2e0.</h2><a href=\\"https://baymard.com/blog/drop-down-usability\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://baymard.com/blog/drop-down-usability</a><a href=\\"https://joshwayne.com/posts/the-problem-with-dropdowns/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://joshwayne.com/posts/the-problem-with-dropdowns/</a><p data-notion-block-id=\\"85f94217-3850-40c2-bb79-34138b43d586\\">\ub450 \uae00\uc740 \uac01\ub3c4\ub294 \ub2e4\ub974\uc9c0\ub9cc \uac19\uc740 \uacb0\ub860\uc73c\ub85c \ubaa8\uc785\ub2c8\ub2e4. \ub4dc\ub86d\ub2e4\uc6b4\uc740 \ub2e8\uc21c\ud574 \ubcf4\uc5ec\uc11c \ub514\uc790\uc774\ub108\uac00 \ub108\ubb34 \ube68\ub9ac \uc190\uc744 \ubed7\ub294 \uae30\ubcf8\uac12\uc778\ub370, \uc2e4\uc81c\ub85c\ub294 \ubd88\ud544\uc694\ud55c \ub9c8\ucc30\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \uae00\uc740 \uc0ac\uc6a9\uc131 \ud14c\uc2a4\ud2b8, \ub450 \ubc88\uc9f8 \uae00\uc740 \ub9ce\uc740 \uc5f0\uad6c \ud14c\uc2a4\ud2b8\ub97c \uae30\ubc18\uc73c\ub85c, \ubb38\uc81c\uc640 \uc81c\uc548\uc744 \uc81c\uc2dc\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"c5f2486a-9036-49aa-902d-fcc8f3bb2afe\\" id=\\"c5f2486a-9036-49aa-902d-fcc8f3bb2afe\\">\uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\ub294 \uc544\uc9c1\ub3c4 \ud480\uc2a4\ud0dd \ubaa8\ub4c8\uc744 \ubc30\ud3ec\ud558\uc9c0 \ubabb\ud55c\ub2e4</h2><a href=\\"https://wasp.sh/blog/2026/06/22/javascript-still-cant-ship-a-full-stack-module\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://wasp.sh/blog/2026/06/22/javascript-still-cant-ship-a-full-stack-module</a><p data-notion-block-id=\\"98883cb9-52c9-4bc4-bf15-aeb10dc6af0a\\">\uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uc5d4 \ud504\ub860\ud2b8\xb7\ubc31\uc5d4\ub4dc\xb7DB\ub97c \ud55c \ub369\uc5b4\ub9ac\ub85c \ubb36\uc5b4 \ubc30\ud3ec\ud558\ub294 \ud45c\uc900 \ud480\uc2a4\ud0dd \ubaa8\ub4c8 \uce35\uc774 \uc5c6\ub2e4\ub294 \ubb38\uc81c \uc81c\uae30\uc785\ub2c8\ub2e4. \uae30\ub2a5\uc744 \uc218\uc9c1 \uc2ac\ub77c\uc774\uc2a4\ub85c \ubcf4\ub294 \ud504\ub808\uc774\ubc0d\uacfc \uc0ac\ub78c\uc5d0\uac8c \uc88b\uc740 \uac8c LLM\uc5d0\uac8c\ub3c4 \uc88b\ub2e4\ub294 \uc815\ub9ac\uac00 \uc77d\uc744 \ub9cc\ud558\uc9c0\ub9cc, \ud574\ubc95\uc740 \uacb0\uad6d \uc800\uc790 \ub3c4\uad6c Wasp \uc885\uc18d\uc774\ub77c \uc9c4\ub2e8\ub9cc \ub5bc\uc5b4 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"38be548d-8a8e-818c-8454-d7a85b691658\\" id=\\"38be548d-8a8e-818c-8454-d7a85b691658\\">AI\ub294 \uc811\uadfc\uc131 \ud14c\uc2a4\ud2b8\ub97c \ud1b5\uacfc\ud558\uc9c0 \ubabb\ud55c\ub2e4</h2><a href=\\"https://www.aaron-gustafson.com/notebook/can-your-ai-pass-the-accessibility-test/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.aaron-gustafson.com/notebook/can-your-ai-pass-the-accessibility-test/</a><p data-notion-block-id=\\"b79276df-d070-4399-9812-a6632cfb71d8\\">AI\uc5d0 \uc811\uadfc\uc131\uc744 \ub9e1\uae30\uba74 \uc5b4\ub514\uae4c\uc9c0 \ub418\uace0 \uc5b4\ub514\uc11c \uba48\ucd94\ub294\uac00. \uadf8 \uacbd\uacc4\uac00 \uc5b4\ub514\uc11c \uac08\ub9ac\ub294\uc9c0\uac00 \uc774 \uae00\uc758 \ud575\uc2ec\uc774\ub77c, \uacb0\ub860\uc740 \uc9c1\uc811 \ud655\uc778\ud558\ub294 \uac8c \ub0ab\uc2b5\ub2c8\ub2e4. \uac19\uc740 \ubb38\uc81c\ub97c \ub2e4\ub978 \uac01\ub3c4\uc5d0\uc11c \uc9da\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/34ae548d-8a8e-8089-b1db-c322e570f0aa#358e548d-8a8e-80e3-82b8-c9ee8c4537f8\\">AI\uac00 \ub9cc\ub4e0 UI\uc5d0 \uc811\uadfc\uc131\uc744 \uc5b4\ub5bb\uac8c \ub354\ud560\uae4c</a>\uc640 \ud568\uaed8 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"38be548d-8a8e-813b-ad3e-c53b205572c3\\" id=\\"38be548d-8a8e-813b-ad3e-c53b205572c3\\">PACT \uc790\uaca9 \uc99d\uba85 \uc81c\uc548\uc11c</h2><a href=\\"https://hacks.mozilla.org/2026/06/pact-anonymous-credentials-for-the-web/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://hacks.mozilla.org/2026/06/pact-anonymous-credentials-for-the-web/</a><p data-notion-block-id=\\"38be548d-8a8e-8172-aaab-d4ace76443ae\\">\ube0c\ub77c\uc6b0\uc800 \ud504\ub77c\uc774\ubc84\uc2dc\uc640 AI \ubc1c\uc804\uc73c\ub85c \ubd07 \uad6c\ubd84\uc774 \uc5b4\ub824\uc6cc\uc9c0\uba74\uc11c, \ud504\ub77c\uc774\ubc84\uc2dc\ub97c \uc9c0\ud0ac\uc218\ub85d \ucea1\ucc28\xb7\uac00\uc785\ubcbd\uc73c\ub85c \ub354 \ubd88\ud3b8\ud574\uc9c0\ub294 \uc5ed\uc124\uc744 \uaca8\ub0e5\ud558\ub294 \uc81c\uc548\uc785\ub2c8\ub2e4. \uc544\uc9c1 \uc81c\uc548\uc774\uae34 \ud558\uc9c0\ub9cc, AI \ubd07\uc5d0 \ub300\ud55c \ud2b8\ub798\ud53d\uc744 \uaca8\ub0e5\ud55c \ub9cc\ud07c \ud55c \ubc88 \uad00\uc2ec \ubaa9\ub85d\uc5d0 \ub4f1\ub85d\ud574\ubcfc\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"ec65ac3b-dbc7-472d-8960-9faddee0c7fd\\" id=\\"ec65ac3b-dbc7-472d-8960-9faddee0c7fd\\">How modern browsers work \uc5c5\ub370\uc774\ud2b8</h2><a href=\\"https://x.com/addyosmani/status/2068394292796871019\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://x.com/addyosmani/status/2068394292796871019</a><p data-notion-block-id=\\"49b2ba2f-13c7-4186-b8ce-2defdf4c843e\\">\ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc758 \ub3d9\uc791 \uc804 \uacfc\uc815\uc744 \uc815\ub9ac\ud55c \uae00\uc744 \uc5c5\ub370\uc774\ud2b8\ud588\uc2b5\ub2c8\ub2e4.\ub124\ud2b8\uc6cc\ud0b9 \uc2a4\ud0dd~GPU \ub80c\ub354\ub9c1\uae4c\uc9c0, \ub610\ud55c V8\uc758 \uc2e4\ud589 \uc9c4\ud654(Ignition \uc778\ud130\ud504\ub9ac\ud130\uc5d0\uc11c <a href=\\"https://v8.dev/blog/maglev\\">Maglev</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/1c3e548d-8a8e-80a7-9539-cddcd66b5f38#1c9e548d-8a8e-800b-8cff-de429634e21b\\">TurboFan</a> \uae4c\uc9c0), \ubcf4\uc548\uc744 \uc9c0\ud0a4\ub294 \uad6c\uc870\ub97c \ub2e4\ub8f9\ub2c8\ub2e4. \ube0c\ub77c\uc6b0\uc800\ub9c8\ub2e4 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0\ub3c4 \uad6c\ubd84\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"38be548d-8a8e-8169-bd5b-c590ae9d7f8e\\" id=\\"38be548d-8a8e-8169-bd5b-c590ae9d7f8e\\">WebSocket \ub77c\uc774\ube0c\ub7ec\ub9ac \ubca4\uce58\ub9c8\ud06c</h2><a href=\\"https://evilmartians.com/chronicles/choose-your-fighter-benchmarking-5-websocket-servers-for-nodejs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://evilmartians.com/chronicles/choose-your-fighter-benchmarking-5-websocket-servers-for-nodejs</a><p data-notion-block-id=\\"38be548d-8a8e-8180-9997-c96ca6e90e22\\">Node.js WebSocket \uc11c\ubc84\uc6a9 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc744 \ube44\uad50\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"38be548d-8a8e-819e-94a2-c60565070970\\" id=\\"38be548d-8a8e-819e-94a2-c60565070970\\">React \ucee4\uc2a4\ud140 \ub80c\ub354\ub7ec \ub9cc\ub4dc\ub294 \ubc95</h2><a href=\\"https://www.callstack.com/blog/writing-custom-renderers-for-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/writing-custom-renderers-for-react</a><h3 data-notion-block-id=\\"4d771949-1994-4947-b75b-290930a79cc2\\">platformatic \u2014 Medusa on Kubernetes / Watt monorepo</h3><a href=\\"https://blog.platformatic.dev/run-medusa-kubernetes-watt-monorepo\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.platformatic.dev/run-medusa-kubernetes-watt-monorepo</a><h1 data-notion-block-id=\\"82edf2da-7565-44f4-9adc-54a89b7d5c0c\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://ast-grep.github.io/blog/ast-grep-outline.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ast-grep.github.io/blog/ast-grep-outline.html</a><p data-notion-block-id=\\"38be548d-8a8e-8163-971e-dba5aee92396\\">ast-grep outline\uc740 \ud30c\uc77c \uc804\uccb4\ub97c \uc77d\uc9c0 \uc54a\uace0 \ud568\uc218\xb7\ud074\ub798\uc2a4\xb7import\xb7export\uc640 \uc704\uce58\ub9cc \ubf51\uc544 \uad6c\uc870 \uc694\uc57d\uc744 \ub9cc\ub4dc\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4. \uc5d0\uc774\uc804\ud2b8 grep\uc758 \ub2e8\uc21c\ud568\uacfc language server\uc758 \ubcf5\uc7a1\ud568 \uc0ac\uc774\ub97c \uba54\uc6b0\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4.</p><a href=\\"https://astro.build/blog/astro-7/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://astro.build/blog/astro-7/</a><p data-notion-block-id=\\"bfca0951-1494-4bb6-9092-74e1f77121dd\\">Astro 7\uc740 .astro \ucef4\ud30c\uc77c\ub7ec\uc640 Markdown\xb7MDX \ucc98\ub9ac\ub97c Rust\ub85c \uac08\uc544\ub07c\uc6b0\uace0 Vite 8 Rolldown\uacfc \ub9de\ubb3c\ub824 \ube4c\ub4dc\ub97c 15~61% \ub2f9\uacbc\uc2b5\ub2c8\ub2e4. Advanced Routing\uacfc \ub77c\uc6b0\ud2b8 \uce90\uc2f1\uc774 \uae30\ubcf8 \ud65c\uc131\ud654\ub410\uace0 \ucd5c\uc18c \uc694\uac74\uc740 Node 22\uc785\ub2c8\ub2e4.</p><a href=\\"https://vite.dev/blog/announcing-vite8-1\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vite.dev/blog/announcing-vite8-1</a><p data-notion-block-id=\\"3c22abdc-eb7e-4d5a-a22b-364dc01cd11e\\">Vite 8.1\uc758 \ud575\uc2ec\uc740 Bundled Dev Mode(\uc2e4\ud5d8)\ub85c, \ud070 \uc571\uc5d0\uc11c dev \uc2dc\uc791 15\ubc30\xb7\uc804\uccb4 \ub9ac\ub85c\ub4dc 10\ubc30\uac00 \ube68\ub77c\uc84c\uc2b5\ub2c8\ub2e4. Lightning CSS \ud1b5\ud569\ub3c4 \ub4e4\uc5b4\uc640 PostCSS\ub97c \ub300\uccb4\ud560 \uae38\uc744 \uc5f4\uc5c8\uace0 \uc804\ubd80 opt-in\uc785\ub2c8\ub2e4.</p><a href=\\"https://babeljs.io/blog/2026/06/16/8.0.0/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://babeljs.io/blog/2026/06/16/8.0.0/</a><p data-notion-block-id=\\"943ccf1e-f781-481b-a632-1fccfbf31286\\">8\ub144 \ub9cc\uc758 \uba54\uc774\uc800\uc778\ub370 \uc0c8 \uae30\ub2a5\uc740 \uc5c6\uc2b5\ub2c8\ub2e4. ESM \uc804\uc6a9\uc73c\ub85c \ubc14\ub00c\uace0 ES5\xb7CommonJS \uae30\ubcf8 \ucef4\ud30c\uc77c\uc744 \uba48\ucdb0 evergreen \ud0c0\uae43\uc5d0\uc11c \ubc88\ub4e4\uc774 \uc904\uba70, Babel 7\uc740 2027\ub144 6\uc6d4\uae4c\uc9c0 \ubcf4\uc548 \ud328\uce58\ub9cc \ubc1b\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://nodejs.org/en/blog/release/v26.4.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodejs.org/en/blog/release/v26.4.0</a><p data-notion-block-id=\\"4686d839-54d0-4eb4-ad40-4037aaa7412e\\"><code>node:vfs</code>\ub85c \uac00\uc0c1 \ud30c\uc77c\uc2dc\uc2a4\ud15c\uc744 \ub9c8\uc6b4\ud2b8\ud558\ub294 \ucd5c\uc18c \uc11c\ube0c\uc2dc\uc2a4\ud15c\uc774 \ub4e4\uc5b4\uc654\uace0 <code>fs/promises</code>\uac00 \uac70\uae30\ub85c \uc5f0\uacb0\ub429\ub2c8\ub2e4. \ubaa8\ub4c8 \ub85c\ub354 package maps, TLS \uc778\uc99d\uc11c \uc555\ucd95, dgram \ub3d9\uae30 \uc18c\ucf13 \uba54\uc11c\ub4dc\ub3c4 \ud568\uaed8 \uc654\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://docs.deno.com/runtime/desktop/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://docs.deno.com/runtime/desktop/</a><p data-notion-block-id=\\"0e12d160-25e2-4b3a-bb92-de1c4065e374\\">Deno 2.9\uc758 Deno Desktop\uc740 TypeScript\ub098 Next.js\xb7Astro \uac19\uc740 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc2e4\ud589 \ubc14\uc774\ub108\ub9ac\ub85c \ucef4\ud30c\uc77c\ud569\ub2c8\ub2e4. Electron \uc5c6\uc774 OS \ub0b4\uc7a5 WebView\ub97c \uc368 \uacb0\uacfc\ubb3c\uc774 \ud6e8\uc52c \uc791\uace0(macOS \uc57d 68MB \ub300 309MB), WebGPU\xb7Skia\ub85c \uc9c1\uc811 \uadf8\ub9ac\ub294 Raw \ubaa8\ub4dc\ub294 \uc544\uc9c1 canary\uc785\ub2c8\ub2e4.</p><a href=\\"https://react.dev/reference/react/Fragment#fragmentinstance\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react.dev/reference/react/Fragment#fragmentinstance</a><p data-notion-block-id=\\"25e4c1ae-d486-4896-87d1-b20d20cb41be\\">Fragment\uc5d0 ref\ub97c \ub2ec \uc218 \uc788\uac8c \ub410\uc2b5\ub2c8\ub2e4(canary). ref\ub97c \uc8fc\uba74 FragmentInstance\uac00 \ub098\uc640 \ub798\ud37c \uc5d8\ub9ac\uba3c\ud2b8 \uc5c6\uc774 \uac10\uc2fc \uc790\uc2dd \uc694\uc18c\uc5d0 \uc774\ubca4\ud2b8\xb7focus\xb7observer\ub97c \uc9c1\uc811 \ubd99\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://github.blog/changelog/2026-06-25-actions-steps-can-now-be-run-in-parallel/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.blog/changelog/2026-06-25-actions-steps-can-now-be-run-in-parallel/</a><p data-notion-block-id=\\"38de548d-8a8e-8034-8f5b-d0e23d148ab2\\">GitHub Actions\uac00 \ud55c job \uc548\uc5d0\uc11c step\uc744 \ubcd1\ub82c\ub85c \ub3cc\ub9b4 \uc218 \uc788\uac8c \ub410\uc2b5\ub2c8\ub2e4. background\ub85c \ube44\ub3d9\uae30 \uc2e4\ud589, wait\xb7cancel\ub85c \uc81c\uc5b4, parallel\ub85c \ub3d9\uc2dc \uc2e4\ud589\uc744 \uc9c0\uc6d0\ud574 \uc21c\ucc28 \uc2e4\ud589\ub9cc \ub418\ub358 \uc81c\uc57d\uc744 \ud481\ub2c8\ub2e4.</p><a href=\\"https://rspack.rs/blog/announcing-2-1\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://rspack.rs/blog/announcing-2-1</a><p data-notion-block-id=\\"40aa0a78-a61e-4684-a023-b98b12599f4f\\">Rspack 2.1\uc740 React Compiler\ub97c Rust\ub85c \ud3ec\ud305\ud574 dev \ucef4\ud30c\uc77c\uc744 Babel \ub300\ube44 13.5\ubc30 \ub2f9\uacbc\uace0, pureFunctions\uac00 \uae30\ubcf8 \ucf1c\uc838 \uc2e4\ud589\ub418\uc9c0 \uc54a\ub294 \ubd84\uae30\uae4c\uc9c0 \ud2b8\ub9ac\uc250\uc774\ud0b9\ud569\ub2c8\ub2e4.</p><a href=\\"https://nextjs.org/blog/next-16-3-instant-navigations\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/next-16-3-instant-navigations</a><p data-notion-block-id=\\"10815a94-eee1-46f8-89d1-cc2a4604d8bb\\">Next.js 16.3\uc758 Instant Navigations\ub294 \uc11c\ubc84 \ubaa8\ub378\uc744 \uc720\uc9c0\ud558\uba74\uc11c \ub9c1\ud06c \ubc18\uc751\uc744 SPA\ucc98\ub7fc \ub9cc\ub4ed\ub2c8\ub2e4. Cache Components\ub85c \uc2a4\ud2b8\ub9ac\ubc0d\xb7\uce90\uc2dc\ub97c \uace0\ub974\uace0, \ud504\ub9ac\ud398\uce58\ub97c \ub77c\uc6b0\ud2b8\ub2f9 \uc7ac\uc0ac\uc6a9 \uc178 \ud558\ub098\ub85c \uc904\uc785\ub2c8\ub2e4(preview).</p><h2 data-notion-block-id=\\"389e548d-8a8e-807a-842a-e2e82e325f81\\" id=\\"389e548d-8a8e-807a-842a-e2e82e325f81\\">\ubc88\uc678: \ucf54\ub4dc\uac00 \uc544\ub2c8\ub77c \uc815\ucc45\uc744 \uacf5\uc720\ud558\ub77c</h2><a href=\\"https://www.jayfreestone.com/writing/share-the-policy-not-the-code/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jayfreestone.com/writing/share-the-policy-not-the-code/</a><p data-notion-block-id=\\"389e548d-8a8e-802b-9e2d-d2c6d13d2ae4\\">\ud504\ub860\ud2b8\uc5d4\ub4dc\uc640 \ubc31\uc5d4\ub4dc\uac00 \uac19\uc740 \ube44\uc988\ub2c8\uc2a4 \uaddc\uce59\uc744 \uac01\uc790 \ub4e4\uace0 \uc788\uc73c\uba74 \uacb0\uad6d \uc5b4\uae0b\ub098\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \uadf8 \ubb38\uc81c\ub97c \ucf54\ub4dc \uacf5\uc720, \uacb0\uc815 \uc804\ub2ec, \uc815\ucc45 \uc804\ub2ec \uc138 \uac00\uc9c0 \ubc29\ubc95\uc73c\ub85c \ub098\ub220 \ube44\uad50\ud569\ub2c8\ub2e4. \uadf8\uc911 \ucf54\ub4dc \uacf5\uc720\ub294 \uc11c\ub85c \ub530\ub85c \ubc30\ud3ec\ub418\ub2e4 \ubcf4\uba74 \ubc84\uc804\uc774 \uc5b4\uae0b\ub098\uc11c \uad8c\ud558\uc9c0 \uc54a\uace0, \ubc31\uc5d4\ub4dc\uac00 \ud310\ub2e8\ud55c \uacb0\uacfc\ub97c \uadf8\ub300\ub85c \ub0b4\ub824\uc8fc\ub294 \ubc29\uc2dd(\ud5c8\uc6a9\ub41c \uc561\uc158\ub9cc \ub2f4\uc544 \ubcf4\ub0b4\uac70\ub098 viewerCanUpdate \uac19\uc740 \ud544\ub4dc\ub97c \uc8fc\ub294 \uc2dd)\uc744 \ub354 \ub0ab\uac8c \ubd05\ub2c8\ub2e4. \uaddc\uce59\uc744 \ud3c9\uac00\ud558\ub294 \uc5d4\uc9c4\uc740 \uc6ec\ub9cc\ud574\uc120 \uadf8\ub300\ub85c\uc9c0\ub9cc \uaddc\uce59 \uc790\uccb4\ub294 \uc790\uc8fc \ubc14\ub00c\ub2c8, \uadf8 \ub458\uc744 \ubd99\uc5ec\ub450\uc9c0 \ub9d0\ub77c\ub294 \uac8c \uae00\uc758 \uc694\uc810\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"38ae548d-8a8e-80a8-92a7-ff1f18d7ba64\\" id=\\"38ae548d-8a8e-80a8-92a7-ff1f18d7ba64\\">\ubc88\uc678: \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c \uc804\uc7c1\uc758 \uad50\ud6c8, \uadf8\ub9ac\uace0 AI</h2><a href=\\"https://nx.dev/blog/meta-harnesses-agents-and-lessons-from-the-framework-wars\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nx.dev/blog/meta-harnesses-agents-and-lessons-from-the-framework-wars</a><p data-notion-block-id=\\"216f6f02-a728-4458-9377-3532454856b4\\">\uc774 \uae00\uc740 \uc9c0\uae08\uc758 AI \uc5d0\uc774\uc804\ud2b8 \ud310\uc774 2010\ub144\ub300 \ud504\ub808\uc784\uc6cc\ud06c \uc804\uc7c1\uc744 \uadf8\ub300\ub85c \ubc18\ubcf5\ud55c\ub2e4\uace0 \ubd05\ub2c8\ub2e4. \uc791\uac8c \uc2dc\uc791\ud55c \ub9ac\uc561\ud2b8\uac00 \uc774\uae30\uace0 Next.js\uac00 \uadf8 \ube48\ud2c8\uc744 \uba54\uc6e0\ub4ef, \uc5d0\uc774\uc804\ud2b8\ub3c4 \ubaa8\ub378\uc774 \uc544\ub2c8\ub77c \uadf8 \uc704\uc758 \ud558\ub2c8\uc2a4 \uce35\uc5d0\uc11c \ucc28\uc774\uac00 \ub09c\ub2e4\ub294 \uac8c \uc694\uc9c0\uc785\ub2c8\ub2e4. \ube44\uc720\ub294 \uc798 \ub9de\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uae00\uc774 \uc800\uc790\uac00 \ub9cc\ub4e0 Polygraph \ubc1c\ud45c\ub85c \ub05d\ub098\uae30 \ub54c\ubb38\uc5d0, \uc5ed\uc0ac\uac00 \ubc18\ubcf5\ub41c\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uc870\uae08 \uac10\uc548\ud574\uc11c \uc77d\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4. \uac8c\ub2e4\uac00 \uae00 \uc2a4\uc2a4\ub85c \uc2dc\uc7a5\uc774 \ud30c\ud3b8\ud654\ub420 \uc218 \uc788\ub2e4\uace0 \uc778\uc815\ud558\ub294\ub370, \uc774\uac74 Next.js\ucc98\ub7fc \ud558\ub098\ub85c \uc218\ub834\ud55c\ub2e4\ub294 \ube44\uc720\uc640 \ubd80\ub52a\ud788\ub294 \ub300\ubaa9\uc774\ub77c \uadf8 \ud2c8\uae4c\uc9c0 \uac19\uc774 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p>"}')}}]);